import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import { createSearchBar } from "../components/SearchBar.js";
import { normalizeHomepageUrl } from "../utils/homepageUrl.js";

class FakeClassList {
  constructor(element) {
    this.element = element;
    this.values = new Set();
  }

  add(...names) {
    names.forEach((name) => this.values.add(name));
  }

  remove(...names) {
    names.forEach((name) => this.values.delete(name));
  }

  contains(name) {
    return this.values.has(name);
  }
}

class FakeElement {
  constructor(tagName) {
    this.tagName = tagName.toUpperCase();
    this.children = [];
    this.listeners = new Map();
    this.attributes = new Map();
    this.classList = new FakeClassList(this);
    this.dataset = {};
    this.style = {};
    this.value = "";
  }

  set className(value) {
    this.classList.values = new Set(value.split(/\s+/).filter(Boolean));
  }

  get className() {
    return [...this.classList.values].join(" ");
  }

  appendChild(child) {
    this.children.push(child);
    child.parentNode = this;
    return child;
  }

  setAttribute(name, value) {
    this.attributes.set(name, String(value));
  }

  addEventListener(type, listener) {
    const listeners = this.listeners.get(type) ?? [];
    listeners.push(listener);
    this.listeners.set(type, listeners);
  }

  dispatch(type, event = {}) {
    event.target ??= this;
    event.stopPropagation ??= () => {};
    event.preventDefault ??= () => {};
    for (const listener of this.listeners.get(type) ?? []) listener(event);
  }

  contains(node) {
    return node === this || this.children.some((child) => child.contains(node));
  }

  closest() {
    return null;
  }

  focus() {}

  blur() {}
}

test("Enter web search clears the field and notifies the public query handler", () => {
  const opened = [];
  globalThis.document = {
    createElement: (tagName) => new FakeElement(tagName),
    addEventListener() {},
  };
  globalThis.chrome = {
    tabs: {
      create: (options) => opened.push(options),
    },
    storage: {
      sync: {
        set() {},
        get: async () => ({}),
      },
      onChanged: {
        addListener() {},
      },
    },
  };

  const container = new FakeElement("div");
  const searchBar = createSearchBar(container);
  const input = container.children[0].children[1];
  const notifications = [];
  searchBar.onBrowserQuery = (...args) => notifications.push(args);

  input.value = "fresh results";
  input.dispatch("input");
  input.dispatch("keydown", { key: "Enter" });

  assert.deepEqual(opened, [
    { url: "https://www.google.com/search?q=fresh%20results" },
  ]);
  assert.equal(input.value, "");
  assert.deepEqual(notifications.at(-1), [null, "all"]);
});

test("homepage URLs must be absolute HTTP(S) URLs and are normalized", () => {
  assert.equal(normalizeHomepageUrl(""), "");
  assert.equal(normalizeHomepageUrl("  https://Example.COM/path?q=hello world  "),
    "https://example.com/path?q=hello%20world");
  assert.equal(normalizeHomepageUrl("http://example.com:80"), "http://example.com/");

  for (const value of [
    "example.com",
    "/relative/path",
    "javascript:alert(1)",
    "ftp://example.com",
    "https://",
  ]) {
    assert.equal(normalizeHomepageUrl(value), null, value);
  }
});

test("settings feedback and guarded homepage navigation use the shared validator", async () => {
  const [settings, meridian] = await Promise.all([
    readFile(new URL("../components/SettingsPanel.js", import.meta.url), "utf8"),
    readFile(new URL("../meridian.js", import.meta.url), "utf8"),
  ]);

  assert.match(settings, /normalizeHomepageUrl\(homepageInput\.value\)/);
  assert.match(settings, /setCustomValidity\(message\)/);
  assert.match(settings, /aria-invalid/);
  assert.match(settings, /complete http:\/\/ or https:\/\//);
  assert.match(meridian, /normalizeHomepageUrl\(homepageUrl \?\? ""\)/);
  assert.match(meridian, /try \{[\s\S]*chrome\.tabs\.update[\s\S]*\} catch \(error\)/);
});

test("sidebar tab and result rows expose keyboard activation and visible focus", async () => {
  const paths = [
    "../components/sidebar.js",
    "../meridian-extension/components/sidebar.js",
  ];
  const cssPaths = [
    "../components/sidebar.css",
    "../meridian-extension/components/sidebar.css",
  ];

  for (const path of paths) {
    const source = await readFile(new URL(path, import.meta.url), "utf8");
    assert.match(source, /row\.tabIndex = 0/);
    assert.match(source, /row\.setAttribute\('role', 'button'\)/);
    assert.match(source, /row\.setAttribute\('aria-label', label\)/);
    assert.match(source, /e\.key !== 'Enter' && e\.key !== ' '/);
    assert.ok(
      (source.match(/makeRowInteractive\(/g) ?? []).length >= 4,
      `${path} applies keyboard behavior to tab, previous-tab, and result rows`,
    );
  }

  for (const path of cssPaths) {
    const source = await readFile(new URL(path, import.meta.url), "utf8");
    assert.match(source, /\.tab-row:focus-visible\s*\{/);
    assert.match(source, /\.tab-row:focus-within \.tab-close-btn/);
  }
});

import assert from "node:assert/strict";
import test from "node:test";

import {
  createScopePopup,
  flattenBookmarks,
  findBookmarksBar,
  allBookmarksRoot,
} from "../components/BookmarksButton.js";

// Chrome's getTree() shape: root (id "0") â†’ [Bookmarks Bar (id "1"),
// Other Bookmarks (id "2"), ...]; folders have no `url`, leaves do.
function fixture() {
  return {
    id: "0",
    children: [
      {
        id: "1",
        title: "Bookmarks Bar",
        children: [
          { id: "10", title: "GitHub", url: "https://github.com" },
          {
            id: "11",
            title: "Dev",
            children: [
              { id: "12", title: "MDN", url: "https://developer.mozilla.org" },
            ],
          },
        ],
      },
      {
        id: "2",
        title: "Other Bookmarks",
        children: [
          { id: "20", title: "News", url: "https://news.example" },
          {
            id: "21",
            title: "Recipes",
            children: [
              { id: "22", title: "Soup", url: "https://soup.example" },
            ],
          },
        ],
      },
    ],
  };
}

test("findBookmarksBar resolves the bar by stable id 1", () => {
  const bar = findBookmarksBar(fixture());
  assert.equal(bar.id, "1");
});

test("findBookmarksBar falls back to a title match when id 1 is absent", () => {
  const root = {
    children: [
      { id: "99", title: "Bookmarks Toolbar", children: [] },
      { id: "2", title: "Other", children: [] },
    ],
  };
  assert.equal(findBookmarksBar(root).id, "99");
});

test("flattenBookmarks (Bookmarks Bar view) recurses folders and drops folder nodes", () => {
  const bar = findBookmarksBar(fixture());
  const urls = flattenBookmarks(bar.children).map((b) => b.url);
  assert.deepEqual(urls, [
    "https://github.com",
    "https://developer.mozilla.org",
  ]);
});

test("allBookmarksRoot preserves folder nodes for drill-in (does not flatten)", () => {
  const root = fixture();
  const bar = findBookmarksBar(root);
  const top = allBookmarksRoot(root, bar);

  // Top level = children of non-bar roots: the News leaf + the Recipes folder.
  assert.deepEqual(
    top.map((n) => n.id),
    ["20", "21"],
  );
  const recipes = top.find((n) => n.id === "21");
  assert.ok(!recipes.url, "folder node retains no url");
  assert.deepEqual(
    recipes.children.map((n) => n.url),
    ["https://soup.example"],
    "drilling into a folder exposes its children",
  );
});

test("allBookmarksRoot excludes the bookmarks bar subtree", () => {
  const root = fixture();
  const bar = findBookmarksBar(root);
  const ids = allBookmarksRoot(root, bar).map((n) => n.id);
  assert.ok(!ids.includes("10") && !ids.includes("11"));
});

