.settings-provider-name {
  font-size: 11px;
  line-height: 1.2;
}

.settings-bg-combined-grid,
.settings-bg-photo-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  margin-top: 4px;
}

.settings-bg-swatch {
  aspect-ratio: 16 / 10;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  overflow: hidden;
  transition:
    box-shadow var(--transition),
    transform var(--transition);
  background-size: cover;
  background-position: center;
  padding: 0;
}

.settings-bg-swatch:hover {
  transform: scale(1.05);
}

.settings-bg-swatch.selected {
  box-shadow: 0 0 0 2px var(--accent);
}

.settings-bg-swatch img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
}

/* "None" swatch â€” diagonal stripes to indicate no background */
.settings-bg-swatch--none {
  background: repeating-linear-gradient(
    45deg,
    var(--surface-hover),
    var(--surface-hover) 3px,
    var(--bg) 3px,
    var(--bg) 9px
  );
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text-secondary);
}

.settings-bg-swatch--none:hover {
  color: var(--text-primary);
}

.settings-bg-sublabel-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
  margin-bottom: 4px;
}

.settings-bg-sublabel {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.settings-bg-refresh {
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--accent);
  font-size: 12px;
  font-family: inherit;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.settings-bg-refresh:hover {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

.settings-bg-upload-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 64px;
  margin-top: 8px;
  padding: 16px 12px;
  border-radius: var(--radius-sm);
  border: 1px dashed var(--border);
  background: transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  text-align: center;
  transition:
    border-color var(--transition),
    color var(--transition),
    background var(--transition);
}

.settings-bg-upload-btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 6%, transparent);
}

.settings-bg-upload-btn.drag-over {
  border-color: var(--accent);
  border-style: solid;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, transparent);
}

.settings-bg-upload-btn.selected {
  border-color: var(--accent);
  color: var(--accent);
  border-style: solid;
}

.settings-bg-upload-btn.upload-error {
  border-color: #ef4444;
  color: #ef4444;
}

