      const f = first.get(item),
        l = last.get(item);
      if (!f || !l) continue;
      const dx = f.left - l.left,
        dy = f.top - l.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) continue;
      item.style.transition = "none";
