/* ---- Settings ---- */

/* Shared dropdown shell â€” the bookmarks/history scope view, the
   search-everything results, and settings all render into one of these.
   Anchored beneath the search pill, borderless, separated by shadow alone
   just like the pill itself. */
.search-popup {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  max-height: min(560px, calc(100vh - 120px));
  overflow: hidden auto;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--card-shadow-hover);
  z-index: 100;
}

.search-popup.hidden {
  display: none;
}

/* ---- Browser search results ---- */

#browser-search-results {
  padding: 16px 20px 24px;
}

.search-results-section {
  margin-bottom: 16px;
}

.search-results-section:last-child {
  margin-bottom: 0;
}

.search-results-label {
  padding: 8px 0 4px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--border);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.result-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition);
}

.result-row:hover,
.result-row:focus {
  background: var(--surface-hover);
  outline: none;
}

.result-favicon {
  width: 16px;
  height: 16px;
  border-radius: 2px;
  flex-shrink: 0;
}

.result-favicon.load-failed {
  visibility: hidden;
}

.result-body {
  flex: 1;
  min-width: 0;
}

.result-title,
.result-meta,
.result-context {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.result-title {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 500;
}

.result-meta {
  margin-top: 1px;
  color: var(--text-secondary);
  font-size: 12px;
}

.result-context {
  max-width: 140px;
  color: var(--text-secondary);
  flex-shrink: 0;
  font-size: 12px;
  text-align: right;
}

.search-results-empty {
  padding: 16px 0;
  color: var(--text-secondary);
  font-size: 14px;
  text-align: center;
}

.search-clear-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: none;
  color: var(--text-secondary);
  cursor: pointer;
  flex-shrink: 0;
  font-size: 20px;
  line-height: 1;
  transition:
    background var(--transition),
    color var(--transition);
}

.search-clear-btn:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.search-clear-btn.hidden {
  display: none;
}

.search-web-go {
  width: 100%;
  border: none;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
}

.search-web-go .result-body {
  display: flex;
  flex-direction: column;
}

.bookmarks-panel-header {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.bookmarks-tabs {
  display: flex;
  gap: 4px;
}

.bookmarks-tab {
  flex: 1;
  border: none;
  background: none;
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
}

.bookmarks-tab:hover {
  background: var(--surface-hover);
}
