async function applyStoredAppearance(backgroundOverride = null) {
  const generation = ++appearanceGeneration;
  let bg = backgroundOverride;

  if (!bg) {
    const { theme, background } = await chrome.storage.sync.get([
      "theme",
      "background",
    ]);
    if (generation !== appearanceGeneration) return;
    applyTheme(theme ?? "system");

    api.onScopeChange?.(scope);
    notifyQuery();
  }

  function setScope(requested) {
    applyScope(scope === requested ? "all" : requested);
    input.focus();
  }

  function doSearch() {
    const q = input.value.trim();
    if (!q) return;
    if (scope !== "all") {
      api.onScopedSubmit?.();
      return;
    }
    chrome.tabs.create({ url: currentProvider.url + encodeURIComponent(q) });
    api.clearSearch();
  }

  // Clicking the magnifier submits exactly like pressing Enter in the field.
  logoBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    doSearch();
  });

  input.addEventListener("input", () => {
    updateClearBtn();
    notifyQuery();
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      doSearch();
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      api.onArrowDown?.();
    }
    if (e.key === "Escape") {
      if (scope !== "all") {
        applyScope("all");
      } else {
        input.value = "";
        updateClearBtn();
        notifyQuery();
        input.blur();
      }
    }
  });

  clearBtn.addEventListener("click", () => {
    input.value = "";
    updateClearBtn();
    notifyQuery();
    input.focus();
  });

  // In a scoped mode (bookmarks/history), a click anywhere outside the pill or
  // its popup exits the scope: deselect back to "all" (which closes the popup
