    const insidePill = wrapper.contains(e.target);
    const insidePopup = !!e.target.closest?.("#bookmarks-panel");
    if (insidePill || insidePopup) return;
    applyScope("all");
    input.blur();
  });

  wrapper.appendChild(logoBtn);
  wrapper.appendChild(input);
