+      async group(options) {
+        calls.push(["group", options]);
+        return 7;
+      },
+      async update(tabId, options) {
+        calls.push(["update", tabId, options]);
+      },
+    },
+    tabGroups: {
+      async update(groupId, options) {
+        calls.push(["updateGroup", groupId, options]);
+      },
